            --color-frontend: #06b6d4; /* Cyan */
            --color-backend: #10b981; /* Emerald */
            --color-ai: #8b5cf6; /* Purple */
            --color-db: #f59e0b; /* Amber */
            --color-mobile: #ec4899; /* Pink */
            --color-practice: #3b82f6; /* Blue */
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-main);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.6;
            padding-bottom: 40px;
        }

        /* Navigation */
        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 40px;
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 0;
            background: rgba(10, 10, 15, 0.95);
            backdrop-filter: blur(10px);
            z-index: 100;
        }

        .logo-area {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 600;
            font-size: 1.1rem;
        }

        .avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: linear-gradient(135deg, #3b82f6, #8b5cf6);
            display: grid;
            place-items: center;
            font-weight: bold;
            font-size: 14px;
        }

        .nav-links {
            display: flex;
            gap: 30px;
        }

        .nav-links a {
            color: var(--text-muted);
            text-decoration: none;
            font-size: 0.95rem;
            transition: color 0.2s;
        }

        .nav-links a:hover {
            color: white;
        }

        .social-icons {
            display: flex;
            gap: 20px;
            color: var(--text-muted);
        }

        .social-icons svg {
            width: 18px;
            height: 18px;
            cursor: pointer;
            transition: color 0.2s;
        }

        .social-icons svg:hover { color: white; }

        /* Main Container */
        main {
            max-width: 1200px;
            margin: 80px auto;
            padding: 0 40px;
        }

        header {
            margin-bottom: 60px;
            max-width: 800px;
        }

        .eyebrow {
            text-transform: uppercase;
            letter-spacing: 1.5px;
            font-size: 0.85rem;
            font-weight: 700;
            color: var(--color-ai); /* Default purple for eyebrow or specific */
            margin-bottom: 12px;
            display: inline-block;
        }

        h1 {
            font-size: 3rem;
            font-weight: 700;
            margin-bottom: 16px;
            letter-spacing: -0.02em;
        }

        .subtitle {
            color: var(--text-muted);
            font-size: 1.15rem;
            max-width: 550px;
            line-height: 1.7;
        }

        /* Grid System */
        .grid-container {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        /* Card Component */
        .card {
            background-color: var(--card-bg);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: 28px;
            display: flex;
            flex-direction: column;
            transition: transform 0.2s ease, border-color 0.2s ease;
            height: 100%; /* Ensure full height for alignment */
        }

        .card:hover {
            transform: translateY(-4px);
            border-color: #444;
        }

        .card-header {
            display: flex;
            align-items: center;
            gap: 16px;
            margin-bottom: 12px;
        }

        .icon-wrapper {
            width: 48px;
            height: 48px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .icon-wrapper svg {
            width: 28px;
            height: 28px;
        }

        .header-text h3 {
            font-size: 1.25rem;
            font-weight: 600;
            margin-bottom: 2px;
        }

        .tech-count {
            font-size: 0.75rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .card-desc {
            color: var(--text-muted);
            font-size: 0.95rem;
            margin-bottom: 24px;
            line-height: 1.5;
        }

        .tags-container {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin-top: auto; /* Push to bottom if needed, though usually flow is fine */
        }

        .tag {
            font-size: 0.8rem;
            padding: 6px 12px;
            border-radius: 9999px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 6px;
            border: 1px solid transparent;
        }

        .tag-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background-color: currentColor;
            opacity: 0.9;
        }

